import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import tools.jackson.databind.ObjectMapper;
public class JfrWindowAudit {
 static final ObjectMapper JSON=new ObjectMapper();
 static <K> void add(Map<K,Long> map,K key,long value){map.merge(key,value,Long::sum);}
 static String thread(RecordedEvent e){for(String field:List.of("sampledThread","eventThread","thread")){if(e.hasField(field)){RecordedThread t=e.getThread(field);if(t!=null)return t.getJavaName()!=null?t.getJavaName():"native-"+t.getOSThreadId();}}return "unknown";}
 static String method(RecordedFrame frame){var m=frame.getMethod();return m.getType().getName()+"."+m.getName();}
 static List<String> stack(RecordedEvent e){var s=e.getStackTrace();return s==null?List.of():s.getFrames().stream().map(JfrWindowAudit::method).toList();}
 static List<Map<String,Object>> top(Map<String,Long> counts){return counts.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(25).map(v->Map.<String,Object>of("name",v.getKey(),"value",v.getValue())).toList();}
 static Map<String,Object> pct(List<Double> values){values.sort(Double::compare);var r=new LinkedHashMap<String,Object>();r.put("samples",values.size());for(var p:Map.of("p50",.5,"p95",.95,"p99",.99,"max",1.).entrySet())r.put(p.getKey(),values.isEmpty()?null:values.get(Math.max(0,(int)Math.ceil(p.getValue()*values.size())-1)));return r;}
 static RecordedThread recordedThread(RecordedEvent e){for(String f:List.of("sampledThread","eventThread","thread"))if(e.hasField(f)){var t=e.getThread(f);if(t!=null)return t;}return null;}
 static class Totals {
  long count,min=Long.MAX_VALUE,max; double sum; long[] buckets=new long[64];
  void add(long v){count++;sum+=v;min=Math.min(min,v);max=Math.max(max,v);buckets[v==0?0:64-Long.numberOfLeadingZeros(v)]++;}
  Map<String,Object> out(){return Map.of("count",count,"sum",sum,"min",count==0?0:min,"max",max,"mean",count==0?0:sum/count,"powerOfTwoBuckets",buckets);}
 }
 static Map<String,Object> totals(Map<String,Totals> map){var out=new TreeMap<String,Object>();map.forEach((k,v)->out.put(k,v.out()));return out;}
 static double millis(RecordedEvent e){return e.getDuration().toNanos()/1e6;}
 public static void main(String[] args)throws Exception{
  Path source=Path.of(args[0]);Instant begin=Instant.ofEpochMilli(Long.parseLong(args[1])),end=Instant.ofEpochMilli(Long.parseLong(args[2]));
  var counts=new TreeMap<String,Long>();var cpu=new TreeMap<String,Map<String,Long>>();var alloc=new HashMap<String,Long>();var sites=new HashMap<String,Long>();var io=new HashMap<String,Long>();var exceptions=new HashMap<String,Long>();var ownerIo=new HashMap<String,Long>();var ownerExamples=new ArrayList<Map<String,Object>>();var heap=new ArrayList<Map<String,Object>>();var nativeSamples=new TreeMap<String,Map<String,Object>>();var direct=new ArrayList<Map<String,Object>>();var allocationRanges=new HashMap<String,long[]>();var pause=new ArrayList<Double>();var safepoint=new ArrayList<Double>();var compilation=new ArrayList<Double>();long dataLoss=0;var waitTimes=new TreeMap<String,Totals>();var waitSites=new HashMap<String,Long>();var tlabByThread=new HashMap<String,Long>();var outsideTlabByThread=new HashMap<String,Long>();var customTimes=new TreeMap<String,Totals>();var spinEvidence=new HashMap<String,Long>();var allThreadNames=new TreeSet<String>(); long largestAllocation=0; String largestAllocationClass="unknown"; long ioBytes=0, ioNanos=0; var ioDurations=new HashMap<String,Totals>(); var ioByteTotals=new HashMap<String,Long>(); var gcDetails=new ArrayList<Map<String,Object>>();
  try(var file=new RecordingFile(source)){
   while(file.hasMoreEvents()){
    var e=file.readEvent();String type=e.getEventType().getName();if(type.equals("jdk.DataLoss"))dataLoss++;
    if(e.getStartTime().isBefore(begin)||e.getStartTime().isAfter(end))continue;
    add(counts,type,1);String t=thread(e);allThreadNames.add(t);
    if(type.equals("jdk.ObjectAllocationInNewTLAB")||type.equals("jdk.ObjectAllocationOutsideTLAB")){long size=e.getLong("allocationSize");if(size>largestAllocation){largestAllocation=size;largestAllocationClass=e.getClass("objectClass").getName();}}
    if(type.equals("jdk.GarbageCollection"))gcDetails.add(Map.of("at",e.getStartTime().toString(),"name",e.getString("name"),"cause",e.getString("cause"),"durationMillis",millis(e),"sumOfPausesNanos",e.getDuration("sumOfPauses").toNanos(),"longestPauseNanos",e.getDuration("longestPause").toNanos()));

    if(type.startsWith("surprising.")||type.startsWith("com.surprising."))for(var f:e.getFields())if(f.getName().toLowerCase(Locale.ROOT).contains("nanos")){Object v=e.getValue(f.getName());if(v instanceof Number n && n.longValue()>=0)customTimes.computeIfAbsent(type+" :: "+f.getName(),k->new Totals()).add(n.longValue());}
    switch(type){
     case "jdk.ExecutionSample", "jdk.NativeMethodSample" -> {var s=stack(e);add(cpu.computeIfAbsent(t,k->new HashMap<>()),s.isEmpty()?"unknown":s.getFirst(),1);if(s.stream().anyMatch(v->v.contains("onSpinWait")||v.contains("BusySpinIdleStrategy")||v.contains("Thread.yield")))add(spinEvidence,t,1);}
     case "jdk.ObjectAllocationSample" -> {var klass=e.getClass("objectClass");var s=stack(e);long weight=e.getLong("weight");add(alloc,klass.getName(),weight);add(sites,t+" :: "+(s.isEmpty()?"unknown":s.getFirst()),weight);}
     case "jdk.ThreadAllocationStatistics" -> {long value=e.getLong("allocated"), at=e.getStartTime().toEpochMilli();var rt=recordedThread(e);String id=t+" #"+(rt==null?-1:rt.getJavaThreadId());long[] a=allocationRanges.computeIfAbsent(id,k->new long[]{value,value,0,at,at});if(at<a[3]){a[0]=value;a[3]=at;}if(at>=a[4]){a[1]=value;a[4]=at;}a[2]++;}
     case "jdk.ObjectAllocationInNewTLAB" -> add(tlabByThread,t,e.getLong("tlabSize"));
     case "jdk.ObjectAllocationOutsideTLAB" -> add(outsideTlabByThread,t,e.getLong("allocationSize"));
     case "jdk.ThreadPark", "jdk.JavaMonitorEnter", "jdk.JavaMonitorWait", "jdk.ThreadSleep" -> {long overlap=Math.max(0,Duration.between(e.getStartTime().isBefore(begin)?begin:e.getStartTime(),e.getEndTime().isAfter(end)?end:e.getEndTime()).toNanos());waitTimes.computeIfAbsent(type+" :: "+t,k->new Totals()).add(overlap);var st=stack(e);String site=st.stream().filter(v->v.startsWith("com.surprising.")).findFirst().orElse(st.isEmpty()?"unknown":st.getFirst());add(waitSites,type+" :: "+t+" :: "+site,overlap);}
     case "jdk.GCPhasePause" -> pause.add(millis(e));
     case "jdk.SafepointBegin", "jdk.ExecuteVMOperation" -> safepoint.add(millis(e));
     case "jdk.Compilation" -> compilation.add(millis(e));
     case "jdk.GCHeapSummary" -> heap.add(Map.of("at",e.getStartTime().toString(),"when",e.getString("when"),"heapUsed",e.getLong("heapUsed")));
     case "jdk.FileRead", "jdk.FileWrite", "jdk.SocketRead", "jdk.SocketWrite" -> {
      var s=stack(e);String key=type+" :: "+t+" :: "+(s.isEmpty()?"unknown":s.getFirst());add(io,key,1);ioDurations.computeIfAbsent(key,k->new Totals()).add(e.getDuration().toNanos());
      long byteCount=0;for(String f:List.of("bytesRead","bytesWritten"))if(e.hasField(f))byteCount+=Math.max(0,e.getLong(f));add(ioByteTotals,key,byteCount);

      if(t.contains("trading-owner")){add(ownerIo,key,1);if(ownerExamples.size()<40)ownerExamples.add(Map.of("type",type,"at",e.getStartTime().toString(),"stack",s,"durationMillis",millis(e)));}
     }
     case "jdk.JavaExceptionThrow", "jdk.JavaErrorThrow" -> {var s=stack(e);add(exceptions,t+" :: "+(s.isEmpty()?"unknown":s.getFirst()),1);}
     case "jdk.NativeMemoryUsage" -> {String category=e.getString("type");long committed=e.getLong("committed"),reserved=e.getLong("reserved");long at=e.getStartTime().toEpochMilli();var n=nativeSamples.computeIfAbsent(category,k->new LinkedHashMap<>(Map.of("firstCommitted",committed,"firstReserved",reserved,"minCommitted",committed,"maxCommitted",committed,"firstAt",at,"lastAt",at)));if(at<=(long)n.get("firstAt")){n.put("firstAt",at);n.put("firstCommitted",committed);n.put("firstReserved",reserved);}if(at>=(long)n.get("lastAt")){n.put("lastAt",at);n.put("lastCommitted",committed);n.put("lastReserved",reserved);}n.put("minCommitted",Math.min((long)n.get("minCommitted"),committed));n.put("maxCommitted",Math.max((long)n.get("maxCommitted"),committed));}
     case "jdk.DirectBufferStatistics" -> {var values=new LinkedHashMap<String,Object>();values.put("at",e.getStartTime().toString());for(var field:e.getFields())if(field.getName().equals("count")||field.getName().equals("totalCapacity")||field.getName().equals("memoryUsed"))values.put(field.getName(),e.getValue(field.getName()));direct.add(values);}
     default -> {}
    }
   }
  }
  var cpuTop=new TreeMap<String,Object>();cpu.forEach((t,c)->cpuTop.put(t,top(c)));var deltas=new TreeMap<String,Long>();var rates=new TreeMap<String,Object>();double[] totalRate={0};allocationRanges.forEach((t,a)->{if(a[2]>1&&a[4]>a[3]&&a[1]>=a[0]){long delta=a[1]-a[0];double seconds=(a[4]-a[3])/1000.0,rate=delta/seconds;deltas.put(t,delta);rates.put(t,Map.of("deltaBytes",delta,"observedSeconds",seconds,"bytesPerSecond",rate,"samples",a[2],"firstEpochMillis",a[3],"lastEpochMillis",a[4]));totalRate[0]+=rate;}});
  var out=new LinkedHashMap<String,Object>();out.put("path",source.toString());out.put("steadyStart",begin.toString());out.put("steadyEnd",end.toString());out.put("eventCounts",counts);out.put("gcEvents",gcDetails);out.put("largestObservedAllocationBytes",largestAllocation);out.put("largestObservedAllocationClass",largestAllocationClass);out.put("ioDurationNanos",totals(ioDurations));out.put("ioBytes",ioByteTotals);out.put("dataLoss",dataLoss);out.put("steadyCpuByThread",cpuTop);out.put("allocationSampleWeightedBytesByClass",top(alloc));out.put("allocationSampleWeightedBytesBySite",top(sites));out.put("threadAllocationObservedDeltasBytes",deltas);out.put("threadAllocationObservedTotalBytes",deltas.values().stream().mapToLong(v->v).sum());out.put("gcPhasePauseMillis",pct(pause));out.put("safepointAndVmOperationMillis",pct(safepoint));out.put("compilationMillis",pct(compilation));out.put("heapSamples",heap);out.put("directBufferSamples",direct);out.put("nativeMemoryCategories",nativeSamples);out.put("ioTop",top(io));out.put("ownerSynchronousIoCount",ownerIo.values().stream().mapToLong(v->v).sum());out.put("ownerSynchronousIoTop",top(ownerIo));out.put("ownerSynchronousIoExamples",ownerExamples);out.put("exceptionTop",top(exceptions));out.put("allocationCounterRatesByThread",rates);out.put("allocationCounterObservedBytesPerSecond",totalRate[0]);out.put("waitNanosecondsByTypeAndThread",totals(waitTimes));out.put("waitTopSitesTotalNanoseconds",top(waitSites));out.put("tlabAllocatedRegionsBytesByThread",tlabByThread);out.put("outsideTlabAllocationBytesByThread",outsideTlabByThread);out.put("customNonnegativeNanosFields",totals(customTimes));out.put("spinFrameSamplesByThread",spinEvidence);out.put("observedThreadNames",allThreadNames);out.put("limitations",List.of("CPU includes busy-spin; sampling does not separate useful work","Allocation weights are sampled estimates","Thread allocation excludes short-lived threads and interval edges","GC duration is observed; not a cross