  JSON.writerWithDefaultPrettyPrinter().writeValue(Path.of(args[3]).toFile(),out);System.out.println("jfrAudit=PASS file="+source.getFileName()+" DataLoss="+dataLoss+" ownerIo="+out.get("ownerSynchronousIoCount")+" gcPause="+out.get("gcPhasePauseMillis"));
 }
}

